  h=0.08+ropeS*0.34*mix(0.35,1.0,bs)+rope2*0.13*bs*bband(7.2)+base*0.14+band*0.055*bs
    +wrin*0.14*bs*dAtt+fibV*0.10*bs+pust*0.016*bs+fine*0.13*dAtt+bnoise(vWP*vec3(6.0,13.0,6.0))*0.04*bband(13.0);
