  // directly — a matte base that a separate synthetic glint then had to fake). One
  // coherent cuticle response: PBR specular carries the highlight.
  const mat=new THREE.MeshStandardMaterial({color:0xffffff,roughness:clamp(1.05-.75*(FX.gloss??.5),.3,.9),metalness:0,side:THREE.DoubleSide});
